	@Test
	void consumedValueCommitFailurePoisonsBothWritersAndInvalidatesCachedIds() throws Exception {
		try (PairedStores stores = new PairedStores(directory, largeConfig().setValueHashCacheEnabled(true))) {
			stores.warm();
			stores.begin();
			Value subject = stores.values.createIRI("urn:cached-input");
			long subjectId = stores.values.storeValue(subject);
			stores.triples.storeTriple(subjectId, 7, 11, 9, true);
			stores.triples.writeNamespaceSnapshot(largeNamespace());
			long previousMap = stores.values.replayMapSize();
			stores.values.failNextCommit = true;
			LmdbTransactionRetryException retry = assertThrows(LmdbTransactionRetryException.class,
					stores.values::commit);
			assertTrue(stores.values.replayMapSize() > previousMap);
			assertSame(retry, assertThrows(LmdbTransactionRetryException.class, stores.triples::commit));
			assertSame(retry,
					assertThrows(LmdbTransactionRetryException.class,
							() -> stores.transaction.invoke(() -> stores.values.storeValue(subject))));
			assertEquals(64, count(stores.triples, true));
			assertEquals(Map.of(), stores.triples.readNamespaceSnapshot());
			stores.rollback();
			assertEquals(0, stores.values.abortCallsAfterFailedCommit,
					"A consumed commit handle must never be aborted again by growth or rollback");
			assertEquals(-1, stores.values.getId(subject), "Aborted dictionary IDs must not survive in input caches");
			stores.begin();
			subjectId = stores.values.storeValue(subject);
			stores.triples.storeTriple(subjectId, 7, 11, 9, true);
			stores.triples.writeNamespaceSnapshot(largeNamespace());
			assertEquals(1, replayFiles(stores.triplesDirectory));
			stores.commit();
			assertEquals(subject, stores.values.getValue(subjectId));
			assertEquals(65, count(stores.triples, true));
		}
	}

