	@Test
	void pinnedReaderChurnUsesHighWaterGrowthDespiteSmallLiveContents() throws Exception {
		try (PairedStores stores = new PairedStores(directory, largeConfig());
				var tripleReservation = stores.triples.getTxnManager().reserveReadTxn(false);
				var valueReservation = stores.values.reserveReadSnapshot()) {
			stores.warm();
			try (var pinnedTriples = tripleReservation.startPinned(stores.triples::getDataRevision);
					var pinnedValues = valueReservation.start()) {
				int batchSize = 100_000;
				long[] subjects = new long[batchSize];
				long[] predicates = new long[batchSize];
				long[] objects = new long[batchSize];
				long[] contexts = new long[batchSize];
				Arrays.fill(predicates, 7);
				Arrays.fill(objects, 11);
				Arrays.fill(contexts, 90);
				for (int cycle = 0; cycle < 2; cycle++) {
					for (int i = 0; i < batchSize; i++) {
						subjects[i] = 100_000L + (long) cycle * batchSize + i;
					}
					stores.begin();
					stores.triples.storeTriplesAligned(subjects, predicates, objects, contexts, batchSize, true);
					stores.commit();
					stores.begin();
					stores.triples.removeTriplesByContext(-1, -1, -1, 90, true, ignored -> {
					});
					stores.commit();
				}
				assertEquals(64, count(stores.triples, true), "Removed pages do not make the high-water mark low");
				try (var iterator = stores.triples.getTriples(pinnedTriples, -1, -1, -1, -1, true)) {
					int oldCount = 0;
					while (iterator.next() != null) {
						oldCount++;
					}
					assertEquals(64, oldCount);
				}
				assertTrue(pinnedValues.isCurrent());
				stores.triples.startTransaction();
				stores.triples.writeNamespaceSnapshot(largeNamespace());
				assertEquals(1, replayFiles(stores.triplesDirectory),
						"Recent page growth while old readers pin reuse must keep complete replay tracking");
				stores.rollback();
			}
		}
	}

